producer.properties (Java Kafka example):

Properties props = new Properties();
props.put("bootstrap.servers", "kafka-broker1:9092,kafka-broker2:9092");
props.put("acks", "all"); // wait for rf replicas
props.put("retries", 3);
props.put("batch.size", 16384); // bytes
props.put("linger.ms", 5); // allow small batching delay
props.put("compression.type", "snappy");
props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

// send
Producer<String,String> producer = new KafkaProducer<>(props);
producer.send(new ProducerRecord<>("activity-topic", userId, eventJson));
producer.flush();
producer.close();
